:root {
  --pixel-black: #111;
  --pixel-white: #f8f8f8;
  --pixel-accent: #ffcc00;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #b8c0c8;
  font-family: 'Courier New', Courier, monospace;
  color: var(--pixel-black);
}

.app {
  width: min(92vw, 420px);
  background: #e8e8e8;
  border: 3px solid #111;
  box-shadow: 6px 6px 0 #111;
  padding: 16px;
}

h1 {
  font-size: 1.6rem;
  margin: 0 0 14px;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.counts p {
  display: inline-block;
  margin: 0 12px 12px 0;
  font-weight: bold;
}

.add-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.add-row label {
  font-weight: bold;
}

input[type='text'] {
  flex: 1 1 140px;
  padding: 8px;
  border: 2px solid #111;
  background: #fff;
  font: inherit;
}

button {
  font: inherit;
  font-weight: bold;
  text-transform: uppercase;
  padding: 8px 10px;
  border: 2px solid #111;
  background: #ddd;
  box-shadow: 3px 3px 0 #111;
  cursor: pointer;
}

button:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 #111;
}

input[type='text']:focus-visible,
button:focus-visible,
input[type='checkbox']:focus-visible {
  outline: 3px solid var(--pixel-accent);
  outline-offset: 2px;
}

#todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
  background: #f8f8f8;
  border: 2px solid #111;
  box-shadow: 3px 3px 0 #111;
}

.todo-item.done span {
  text-decoration: line-through;
  opacity: 0.6;
}

.todo-item span {
  flex: 1;
  word-break: break-word;
}

input[type='checkbox'] {
  width: 18px;
  height: 18px;
  accent-color: #111;
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

let tasks = [];
let nextId = 1;

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(task => !task.completed).length;
}

function render() {
  list.innerHTML = '';

  tasks.forEach(task => {
    const li = document.createElement('li');
    li.className = 'todo-item' + (task.completed ? ' done' : '');

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = `todo-check-${task.id}`;
    checkbox.checked = task.completed;
    checkbox.setAttribute('aria-label', 'Mark task complete');

    const text = document.createElement('span');
    text.id = `todo-text-${task.id}`;
    text.textContent = task.text;

    const deleteBtn = document.createElement('button');
    deleteBtn.type = 'button';
    deleteBtn.id = `todo-delete-${task.id}`;
    deleteBtn.textContent = 'Delete';
    deleteBtn.setAttribute('aria-label', 'Delete task');

    checkbox.addEventListener('change', () => {
      task.completed = checkbox.checked;
      li.classList.toggle('done', task.completed);
      updateCounts();
    });

    deleteBtn.addEventListener('click', () => {
      tasks = tasks.filter(t => t.id !== task.id);
      render();
    });

    li.append(checkbox, text, deleteBtn);
    list.appendChild(li);
  });

  updateCounts();
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;

  tasks.push({ id: nextId, text, completed: false });
  nextId += 1;
  input.value = '';
  render();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') {
    event.preventDefault();
    addTask();
  }
});
